            {
                TrackingNumber = "TRK-3003",
                Status = "Processing",
                Location = "Chicago, IL",
                EstimatedDelivery = new DateTimeOffset(2026, 7, 22, 15, 0, 0, TimeSpan.FromHours(-5)),
                StatusUpdates =
