using sv_202bef221b9e401f9239c3503fe14a08.Client.Models;
using sv_202bef221b9e401f9239c3503fe14a08.Client.Services;

namespace sv_202bef221b9e401f9239c3503fe14a08.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly IReadOnlyDictionary<string, Shipment> SeedData =
        new Dictionary<string, Shipment>(StringComparer.OrdinalIgnoreCase)
        {
            ["TRK-1001"] = new Shipment
            {
                TrackingNumber = "TRK-1001",
                Status = "In Transit",
                Location = "Memphis, TN",
                EstimatedDelivery = new DateTimeOffset(2026, 7, 18, 17, 0, 0, TimeSpan.FromHours(-5)),
                StatusUpdates =
                [
                    new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 7, 12, 9, 30, 0, TimeSpan.FromHours(-5)) },
                    new StatusUpdate { Description = "Arrived at sorting facility", Timestamp = new DateTimeOffset(2026, 7, 13, 2, 15, 0, TimeSpan.FromHours(-5)) },
                    new StatusUpdate { Description = "Departed Memphis hub", Timestamp = new DateTimeOffset(2026, 7, 13, 18, 45, 0, TimeSpan.FromHours(-5)) },
                ]
            },
            ["TRK-2002"] = new Shipment
            {
                TrackingNumber = "TRK-2002",
                Status = "Delivered",
                Location = "Seattle, WA",
                EstimatedDelivery = new DateTimeOffset(2026, 7, 10, 12, 0, 0, TimeSpan.FromHours(-7)),
                StatusUpdates =
                [
                    new StatusUpdate { Description = "Package picked up", Timestamp = new DateTimeOffset(2026, 7, 7, 10, 0, 0, TimeSpan.FromHours(-7)) },
                    new StatusUpdate { Description = "In transit to destination", Timestamp = new DateTimeOffset(2026, 7, 8, 14, 0, 0, TimeSpan.FromHours(-7)) },
                    new StatusUpdate { Description = "Out for delivery", Timestamp = new DateTimeOffset(2026, 7, 10, 8, 0, 0, TimeSpan.FromHours(-7)) },
                    new StatusUpdate { Description = "Delivered — signed by J. Smith", Timestamp = new DateTimeOffset(2026, 7, 10, 11, 32, 0, TimeSpan.FromHours(-7)) },
                ]
            },
            ["TRK-3003"] = new Shipment
            {
                TrackingNumber = "TRK-3003",
                Status = "Processing",
                Location = "Chicago, IL",
                EstimatedDelivery = new DateTimeOffset(2026, 7, 22, 15, 0, 0, TimeSpan.FromHours(-5)),
                StatusUpdates =
                [
                    new StatusUpdate { Description = "Label created", Timestamp = new DateTimeOffset(2026, 7, 14, 8, 0, 0, TimeSpan.FromHours(-5)) },
                ]
            },
        };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);

        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

